<?php
session_start();
require_once dirname(__DIR__).'/dbconn.php';
require_once dirname(__DIR__).'/includes/functions.php';
requireRole(['Scholarship Coordinator']);
require_once __DIR__.'/scholarship_files.php';
$coordinator = $_SESSION['role']==='Scholarship Coordinator';
$view=$_GET['view']??'programs';
if(!in_array($view,['programs','applications','monitoring','reports'],true)) $view='programs';
if(!$coordinator && $view!=='programs' && $view!=='applications') {http_response_code(403);exit('Access denied');}
$student=null;
if(!$coordinator){$q=$pdo->prepare('SELECT student_lrn FROM students WHERE user_id=?');$q->execute([$_SESSION['user_id']]);$student=$q->fetchColumn();if(!$student){http_response_code(403);exit('No student profile linked to this account.');}}
$error='';
try {
 if($_SERVER['REQUEST_METHOD']==='POST'){
  verifyCsrf();
  $action=$_POST['action']??'';
  if($action==='apply' && !$coordinator){
   $id=filter_var($_POST['program_id']??null,FILTER_VALIDATE_INT);
   $q=$pdo->prepare("SELECT program_id FROM scholarship_programs WHERE program_id=? AND program_status='Published' AND (application_start IS NULL OR application_start<=CURDATE()) AND (application_deadline IS NULL OR application_deadline>=CURDATE())");$q->execute([$id]);
   if(!$q->fetchColumn())throw new Exception('This program is not currently accepting applications.');
   $q=$pdo->prepare("SELECT 1 FROM enrollments WHERE student_lrn=? AND enrollment_status='Officially Enrolled' LIMIT 1");$q->execute([$student]);if(!$q->fetchColumn())throw new Exception('Official enrollment is required to apply.');
   $q=$pdo->prepare('SELECT 1 FROM scholarship_applications WHERE program_id=? AND student_lrn=? LIMIT 1');$q->execute([$id,$student]);if($q->fetchColumn())throw new Exception('You already applied to this program.');
   $pdo->beginTransaction();$q=$pdo->prepare("INSERT INTO scholarship_applications(program_id,student_lrn,application_date,application_status) VALUES(?,?,CURDATE(),'Pending')");$q->execute([$id,$student]);$appId=(int)$pdo->lastInsertId();
   $q=$pdo->prepare('SELECT required_documents FROM scholarship_programs WHERE program_id=?');$q->execute([$id]);$required=(string)$q->fetchColumn();
   foreach(array_unique(array_filter(array_map('trim',explode(',',$required)))) as $doc){$q=$pdo->prepare("INSERT INTO scholarship_application_documents(application_id,document_name,verification_status) VALUES(?,?,'Not Submitted')");$q->execute([$appId,$doc]);}$pdo->commit();
  } elseif(!$coordinator && $action==='upload'){
   $docId=filter_var($_POST['document_id']??null,FILTER_VALIDATE_INT);
   $q=$pdo->prepare("SELECT d.application_document_id,d.file_path FROM scholarship_application_documents d JOIN scholarship_applications a ON a.application_id=d.application_id WHERE d.application_document_id=? AND a.student_lrn=? AND a.application_status NOT IN ('Approved','Rejected','Withdrawn')");$q->execute([$docId,$student]);$doc=$q->fetch();if(!$doc)throw new Exception('Document is not editable.');
   $f=$_FILES['document_file']??null;if(!$f||$f['error']!==UPLOAD_ERR_OK||$f['size']>5*1024*1024)throw new Exception('Choose a file smaller than 5 MB.');
   $mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png','application/pdf'=>'pdf'][$mime]??null;if(!$ext)throw new Exception('Only JPG, PNG and PDF files are accepted.');
   $dir=dirname(__DIR__).'/storage/scholarship_documents/'.$student;if(!is_dir($dir)&&!mkdir($dir,0750,true))throw new Exception('Unable to create upload directory.');
   $name=bin2hex(random_bytes(16)).'.'.$ext;$path=$dir.'/'.$name;if(!move_uploaded_file($f['tmp_name'],$path))throw new Exception('Upload failed.');
   $q=$pdo->prepare("UPDATE scholarship_application_documents SET file_path=?,verification_status='Pending',verified_by=NULL,verified_at=NULL,remarks=NULL WHERE application_document_id=?");$q->execute(['storage/scholarship_documents/'.$student.'/'.$name,$docId]);
  } elseif($coordinator && $action==='verify_document'){
   $docId=filter_var($_POST['document_id']??null,FILTER_VALIDATE_INT);$status=$_POST['verification_status']??'';if(!in_array($status,['Accepted','Rejected','Pending'],true))throw new Exception('Invalid verification status.');
   $q=$pdo->prepare('SELECT d.file_path,a.application_status,d.application_id,p.required_documents FROM scholarship_application_documents d JOIN scholarship_applications a ON a.application_id=d.application_id JOIN scholarship_programs p ON p.program_id=a.program_id WHERE d.application_document_id=?');$q->execute([$docId]);$doc=$q->fetch();if(!$doc||!$doc['file_path']||!is_file(dirname(__DIR__).'/'.$doc['file_path'])||in_array($doc['application_status'],['Approved','Rejected','Withdrawn'],true))throw new Exception('Document must be uploaded and application editable.');
   $name=trim($_POST['requirement_name']??'');
   if($status==='Accepted' && !in_array($name,scholarshipDocNames($doc['required_documents']),true))throw new Exception('Select the requirement this file satisfies.');
   if($status==='Accepted'){$q=$pdo->prepare("SELECT 1 FROM scholarship_application_documents WHERE application_id=? AND application_document_id<>? AND document_name=? AND verification_status='Accepted'");$q->execute([$doc['application_id'],$docId,$name]);if($q->fetchColumn())throw new Exception('This requirement already has an accepted file.');}
   $q=$pdo->prepare("UPDATE scholarship_application_documents SET document_name=CASE WHEN ?='' THEN document_name ELSE ? END,verification_status=?,verified_by=?,verified_at=NOW(),remarks=? WHERE application_document_id=?");$q->execute([$name,$name,$status,$_SESSION['user_id'],trim($_POST['remarks']??''),$docId]);
  } elseif($coordinator && $action==='provider'){
   $name=trim($_POST['provider_name']??'');if($name==='')throw new Exception('Provider name is required.');
   $type=$_POST['provider_type']??'Community';if(!in_array($type,['Community','Government','NGO','Private','School'],true))throw new Exception('Invalid provider type.');
   $q=$pdo->prepare("INSERT INTO scholarship_providers(provider_name,provider_type,provider_status,created_by) VALUES(?,?,'Active',?)");$q->execute([$name,$type,$_SESSION['user_id']]);
  } elseif($coordinator && $action==='program'){
   $provider=filter_var($_POST['provider_id']??null,FILTER_VALIDATE_INT);$name=trim($_POST['program_name']??'');$slots=filter_var($_POST['available_slots']??null,FILTER_VALIDATE_INT);
   if(!$provider||$name===''||$slots===false||$slots<0)throw new Exception('Enter a provider, program name and valid slots.');
   $q=$pdo->prepare("SELECT 1 FROM scholarship_providers WHERE provider_id=? AND provider_status='Active'");$q->execute([$provider]);if(!$q->fetchColumn())throw new Exception('Provider is not active.');
   $start=$_POST['application_start']?:null;$end=$_POST['application_deadline']?:null;if($start&&$end&&$end<$start)throw new Exception('Deadline must not be earlier than start date.');
   $requiredChoice=$_POST['documents_required']??'';
   if(!in_array($requiredChoice,['yes','no'],true))throw new Exception('Choose whether documents are required.');
   $names=$requiredChoice==='yes'?scholarshipDocNames($_POST['required_documents']??''):[];
   if($requiredChoice==='yes'&&!$names)throw new Exception('Enter the required documents.');
   $keys=array_map('scholarshipFileKey',$names);
   if(in_array('',$keys,true)||count(array_unique($keys))!==count($keys))throw new Exception('Use distinct document names.');
   $requiredText=$names?implode("\n",$names):null;
   $q=$pdo->prepare("INSERT INTO scholarship_programs(provider_id,program_name,description,eligibility_criteria,required_documents,benefits,available_slots,application_start,application_deadline,application_method,program_status,created_by) VALUES(?,?,?,?,?,?,?,?,?,'School Managed','Published',?)");
   $q->execute([$provider,$name,trim($_POST['description']??''),trim($_POST['eligibility_criteria']??''),$requiredText,trim($_POST['benefits']??''),$slots,$start,$end,$_SESSION['user_id']]);
  } elseif($coordinator && $action==='decision'){
   $id=filter_var($_POST['application_id']??null,FILTER_VALIDATE_INT);$status=$_POST['application_status']??'';
   if(!in_array($status,['Pending','For Verification','Verified','Approved','Rejected'],true))throw new Exception('Invalid application status.');
   $pdo->beginTransaction();$q=$pdo->prepare('SELECT application_status FROM scholarship_applications WHERE application_id=? FOR UPDATE');$q->execute([$id]);$old=$q->fetchColumn();if($old===false)throw new Exception('Application not found.');
   if($old==='Approved'&&$status!=='Approved')throw new Exception('An approved award cannot be reversed from this form.');
   if(in_array($old,['Rejected','Withdrawn'],true))throw new Exception('This application is closed.');
   if(in_array($status,['Approved','Verified'],true)){
    $q=$pdo->prepare('SELECT p.program_id,p.required_documents FROM scholarship_programs p JOIN scholarship_applications a ON a.program_id=p.program_id WHERE a.application_id=? FOR UPDATE');$q->execute([$id]);$program=$q->fetch();
    $q=$pdo->prepare('SELECT document_name FROM scholarship_application_documents WHERE application_id=?');$q->execute([$id]);$present=array_map('scholarshipFileKey',$q->fetchAll(PDO::FETCH_COLUMN));foreach(scholarshipDocNames($program['required_documents']) as $name)if(!in_array(scholarshipFileKey($name),$present,true))throw new Exception('Missing required document: '.$name);
   }
   if($status==='Approved'||$status==='Verified'){
    $q=$pdo->prepare("SELECT file_path,verification_status FROM scholarship_application_documents WHERE application_id=?");$q->execute([$id]);foreach($q->fetchAll() as $doc){if($doc['verification_status']!=='Accepted'||!$doc['file_path']||!is_file(dirname(__DIR__).'/'.$doc['file_path']))throw new Exception('All required documents must be uploaded and accepted before approval.');}
   }
   if($status==='Approved'){
    $q=$pdo->prepare('SELECT p.available_slots, (SELECT COUNT(*) FROM scholarship_awards aw JOIN scholarship_applications sa ON sa.application_id=aw.application_id WHERE sa.program_id=p.program_id) AS awarded FROM scholarship_programs p JOIN scholarship_applications a ON a.program_id=p.program_id WHERE a.application_id=?');$q->execute([$id]);$slots=$q->fetch();
    $q=$pdo->prepare('SELECT 1 FROM scholarship_awards WHERE application_id=?');$q->execute([$id]);$already=$q->fetchColumn();
    if(!$already && $slots['available_slots']!==null && (int)$slots['awarded'] >= (int)$slots['available_slots'])throw new Exception('All scholarship slots have been filled.');
    if(!$already){$q=$pdo->prepare("INSERT INTO scholarship_awards(application_id,award_start_date,award_status,renewal_eligibility,recorded_by) VALUES(?,CURDATE(),'Active','Pending',?)");$q->execute([$id,$_SESSION['user_id']]);}
   }
   $q=$pdo->prepare('UPDATE scholarship_applications SET application_status=?,decision_date=?,processed_by=? WHERE application_id=?');$q->execute([$status,in_array($status,['Approved','Rejected'],true)?date('Y-m-d'):null,$_SESSION['user_id'],$id]);$pdo->commit();
  } elseif($coordinator && $action==='distribution'){
   $award=filter_var($_POST['award_id']??null,FILTER_VALIDATE_INT);$description=trim($_POST['assistance_description']??'');$date=$_POST['distribution_date']??'';
   if(!$award||$description===''||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))throw new Exception('Complete the distribution details.');
   $q=$pdo->prepare("SELECT 1 FROM scholarship_awards WHERE award_id=? AND award_status='Active'");$q->execute([$award]);if(!$q->fetchColumn())throw new Exception('Award is not active.');
   $q=$pdo->prepare('INSERT INTO assistance_distributions(award_id,distribution_date,assistance_description,quantity_or_coverage,remarks,recorded_by) VALUES(?,?,?,?,?,?)');$q->execute([$award,$date,$description,trim($_POST['quantity_or_coverage']??''),trim($_POST['remarks']??''),$_SESSION['user_id']]);
  }else throw new Exception('Invalid action.');
  $_SESSION['message']='Scholarship record saved.';header('Location: scholarship.php?view='.urlencode($view));exit;
 }
}catch(Throwable $ex){if($pdo->inTransaction())$pdo->rollBack();$error=$ex->getMessage();}
$providers=$pdo->query("SELECT provider_id,provider_name,provider_type FROM scholarship_providers WHERE provider_status='Active' ORDER BY provider_name")->fetchAll();
$programs=$pdo->query('SELECT p.*,v.provider_name FROM scholarship_programs p JOIN scholarship_providers v ON v.provider_id=p.provider_id ORDER BY p.program_id DESC')->fetchAll();
if($coordinator){$applications=$pdo->query('SELECT a.*,p.program_name,s.first_name,s.last_name FROM scholarship_applications a JOIN scholarship_programs p ON p.program_id=a.program_id JOIN students s ON s.student_lrn=a.student_lrn ORDER BY a.application_id DESC')->fetchAll();}
else{$q=$pdo->prepare('SELECT a.*,p.program_name FROM scholarship_applications a JOIN scholarship_programs p ON p.program_id=a.program_id WHERE a.student_lrn=? ORDER BY a.application_id DESC');$q->execute([$student]);$applications=$q->fetchAll();}
$docs=[];if($coordinator){$docs=$pdo->query('SELECT d.*,a.student_lrn,a.application_status,p.program_name,p.required_documents FROM scholarship_application_documents d JOIN scholarship_applications a ON a.application_id=d.application_id JOIN scholarship_programs p ON p.program_id=a.program_id ORDER BY d.application_document_id DESC')->fetchAll();}else{$q=$pdo->prepare('SELECT d.*,a.application_status,p.program_name FROM scholarship_application_documents d JOIN scholarship_applications a ON a.application_id=d.application_id JOIN scholarship_programs p ON p.program_id=a.program_id WHERE a.student_lrn=? ORDER BY d.application_document_id DESC');$q->execute([$student]);$docs=$q->fetchAll();}
$awards=$coordinator?$pdo->query('SELECT aw.*,a.student_lrn,p.program_name FROM scholarship_awards aw JOIN scholarship_applications a ON a.application_id=aw.application_id JOIN scholarship_programs p ON p.program_id=a.program_id ORDER BY aw.award_id DESC')->fetchAll():[];
$distributions=$coordinator?$pdo->query('SELECT d.*,a.student_lrn,p.program_name FROM assistance_distributions d JOIN scholarship_awards aw ON aw.award_id=d.award_id JOIN scholarship_applications a ON a.application_id=aw.application_id JOIN scholarship_programs p ON p.program_id=a.program_id ORDER BY d.distribution_date DESC')->fetchAll():[];
require dirname(__DIR__).'/includes/header.php';
?>
<h2 class="mb-3"><?=e(['programs'=>'Scholarship Programs','applications'=>'Scholarship Applications','monitoring'=>'Scholarship Monitoring','reports'=>'Scholarship Reports'][$view])?></h2>
<?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;showMessage(); ?>
<?php if($view==='programs'):?>
<?php if($coordinator):?><div class="row g-3 mb-3"><div class="col-12"><div class="card p-3"><h5>Add Provider</h5><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="action" value="provider"><div class="row g-2 align-items-end"><div class="col-md-5"><label>Provider name</label><input required maxlength="180" name="provider_name" class="form-control mb-2"></div><div class="col-md-4"><label>Type</label><select name="provider_type" class="form-select mb-2"><option>Community</option><option>Government</option><option>NGO</option><option>Private</option><option>School</option></select></div><div class="col-md-3"><button class="btn btn-primary mb-2">Add Provider</button></div></div></form></div></div><div class="col-12"><div class="card p-3"><h5>Publish Program</h5><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="action" value="program"><div class="row g-2"><div class="col-md-6"><label>Provider</label><select name="provider_id" class="form-select mb-2" required><?php foreach($providers as $v):?><option value="<?=$v['provider_id']?>"><?=e($v['provider_name'])?></option><?php endforeach;?></select></div><div class="col-md-6"><label>Program name</label><input name="program_name" required class="form-control mb-2"></div><div class="col-md-6"><label>Description</label><textarea name="description" class="form-control mb-2"></textarea></div><div class="col-md-6"><label>Eligibility</label><textarea name="eligibility_criteria" class="form-control mb-2"></textarea></div><div class="col-md-6"><label>Are documents required?</label><select name="documents_required" class="form-select mb-2" id="documents-required" required><option value="no">No</option><option value="yes">Yes</option></select><div id="requirements-box" hidden><label>Required documents (one per line)</label><textarea name="required_documents" id="required-documents" class="form-control mb-2" rows="4" disabled></textarea></div><script>document.getElementById('documents-required').addEventListener('change',function(){const yes=this.value==='yes';document.getElementById('requirements-box').hidden=!yes;const field=document.getElementById('required-documents');field.disabled=!yes;field.required=yes;});</script></div><div class="col-md-6"><label>Benefits</label><input name="benefits" class="form-control mb-2"></div><div class="col-md-6"><label>Slots</label><input name="available_slots" type="number" min="0" required class="form-control mb-2"></div><div class="col-12"><div class="row"><div class="col"><label>Start</label><input type="date" name="application_start" class="form-control mb-2"></div><div class="col"><label>Deadline</label><input type="date" name="application_deadline" class="form-control mb-2"></div></div></div></div><button class="btn btn-primary">Publish</button></form></div></div></div><?php endif;?>
<div class="card p-3"><h5>Programs</h5><div class="table-responsive"><table class="table"><thead><tr><th>Program</th><th>Provider</th><th>Eligibility</th><th>Benefits</th><th>Slots</th><th>Deadline</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($programs as $p):if(!$coordinator&&$p['program_status']!=='Published')continue;?><tr><td><?=e($p['program_name'])?></td><td><?=e($p['provider_name'])?></td><td><?=e($p['eligibility_criteria'])?></td><td><?=e($p['benefits'])?></td><td><?=e($p['available_slots'])?></td><td><?=e($p['application_deadline'])?></td><td><?=e($p['program_status'])?></td><td><?php if(!$coordinator):?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="action" value="apply"><input type="hidden" name="program_id" value="<?=$p['program_id']?>"><button class="btn btn-sm btn-primary">Apply</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div>
<?php elseif($view==='applications'):?>
<?php foreach($programs as $p): $group=array_values(array_filter($applications,fn($a)=>(int)$a['program_id']===(int)$p['program_id'])); ?>
<details class="card p-3 mb-3" <?= $error ? 'open' : '' ?>><summary style="cursor:pointer;font-weight:600"> <?=e($p['program_name'])?> <span class="text-muted small">(<?=count($group)?> applicants)</span></summary>
<?php if(!$group):?><p class="text-muted mt-3 mb-0">No applications yet.</p><?php endif;?>
