<div class="table-responsive"><table class="table"><thead><tr><th>ID</th><th>Student</th><th>Date</th><th>Status</th><?php if($coordinator):?><th>Review</th><?php endif;?></tr></thead><tbody><?php foreach([$a] as $a):?><tr><td><?=e($a['application_id'])?></td><td><?=e($coordinator?($a['first_name'].' '.$a['last_name'].' ('.$a['student_lrn'].')'):$student)?></td><td><?=e($a['application_date'])?></td><td><?=e($a['application_status'])?></td><?php if($coordinator):?><td><form method="post" class="d-flex gap-2"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="action" value="decision"><input type="hidden" name="application_id" value="<?=$a['application_id']?>"><select class="form-select form-select-sm" name="application_status"><?php foreach(['Pending','For Verification','Verified','Approved','Rejected'] as $st):?><option <?=$st===$a['application_status']?'selected':''?>><?=e($st)?></option><?php endforeach;?></select><button class="btn btn-sm btn-primary">Save</button></form></td><?php endif;?></tr><?php endforeach;?></tbody></table></div><h5 class="mt-3">Application Documents</h5><a class="btn btn-sm btn-outline-primary mb-2" target="_blank" rel="noopener" href="scholarship_document.php?application_id=<?=(int)$a['application_id']?>">View Documents</a><div class="table-responsive"><table class="table"><tr><th>Document</th><th>Status</th><th>File</th><th>Action</th></tr><?php foreach($docs as $doc):if((int)$doc['application_id']!==(int)$a['application_id'])continue;?><tr><td><?=e($doc['document_name'])?></td><td><?=e($doc['verification_status'])?></td><td><?php if($doc['file_path'] && is_file(dirname(__DIR__).'/'.$doc['file_path'])):?><a href="scholarship_document.php?id=<?=$doc['application_document_id']?>" target="_blank" rel="noopener">View file</a><?php else:?>Not uploaded<?php endif;?></td><td><?php if($coordinator && $doc['file_path'] && is_file(dirname(__DIR__).'/'.$doc['file_path']) && !in_array($doc['application_status'],['Approved','Rejected','Withdrawn'],true)):?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="action" value="verify_document"><input type="hidden" name="document_id" value="<?=$doc['application_document_id']?>"><select name="requirement_name" class="form-select form-select-sm mb-1"><option value="">Identify requirement</option><?php foreach(scholarshipDocNames($doc['required_documents']) as $requirement):?><option value="<?=e($requirement)?>" <?=$requirement===$doc['document_name']?'selected':''?>><?=e($requirement)?></option><?php endforeach;?></select><select name="verification_status" class="form-select form-select-sm"><?php foreach(['Pending','Accepted','Rejected'] as $st):?><option <?=$st===$doc['verification_status']?'selected':''?>><?=e($st)?></option><?php endforeach;?></select><input name="remarks" placeholder="Remarks" class="form-control form-control-sm"><button class="btn btn-sm btn-primary">Verify</button></form><?php elseif(!$coordinator&&!in_array($doc['application_status'],['Approved','Rejected','Withdrawn'],true)):?><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="action" value="upload"><input type="hidden" name="document_id" value="<?=$doc['application_document_id']?>"><input type="file" name="document_file" accept=".jpg,.jpeg,.png,.pdf" required class="form-control form-control-sm"><button class="btn btn-sm btn-primary">Upload</button></form><?php endif;?></td></tr><?php endforeach;?></table></div></details><?php endforeach;?></details><?php endforeach;?>
<?php elseif($view==='monitoring'&&$coordinator):?><div class="card p-3 mb-3"><h5>Scholarship Awards</h5><table class="table"><tr><th>Award ID</th><th>LRN</th><th>Program</th><th>Status</th></tr><?php foreach($awards as $a):?><tr><td><?=e($a['award_id'])?></td><td><?=e($a['student_lrn'])?></td><td><?=e($a['program_name'])?></td><td><?=e($a['award_status'])?></td></tr><?php endforeach;?></table></div><div class="card p-3 mb-3"><h5>Record Assistance Distribution</h5><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="action" value="distribution"><label>Award</label><select name="award_id" class="form-select mb-2"><?php foreach($awards as $a):if($a['award_status']==='Active'):?><option value="<?=$a['award_id']?>"><?=e($a['program_name'].' — '.$a['student_lrn'])?></option><?php endif;endforeach;?></select><label>Date</label><input name="distribution_date" type="date" required value="<?=date('Y-m-d')?>" class="form-control mb-2"><label>Assistance</label><input name="assistance_description" required class="form-control mb-2"><label>Quantity / Coverage</label><input name="quantity_or_coverage" class="form-control mb-2"><label>Remarks</label><textarea name="remarks" class="form-control mb-2"></textarea><button class="btn btn-primary">Record Distribution</button></form></div><div class="card p-3"><h5>Distribution History</h5><table class="table"><tr><th>Date</th><th>LRN</th><th>Program</th><th>Assistance</th></tr><?php foreach($distributions as $d):?><tr><td><?=e($d['distribution_date'])?></td><td><?=e($d['student_lrn'])?></td><td><?=e($d['program_name'])?></td><td><?=e($d['assistance_description'])?></td></tr><?php endforeach;?></table></div>
<?php elseif($view==='reports'&&$coordinator):?><div class="row g-3"><?php foreach(['Published Programs'=>count(array_filter($programs,fn($p)=>$p['program_status']==='Published')),'Applications'=>count($applications),'Awards'=>count($awards),'Distributions'=>count($distributions)] as $label=>$n):?><div class="col-md-3"><div class="card p-3"><div><?=e($label)?></div><h2><?=$n?></h2></div></div><?php endforeach;?></div><div class="card p-3 mt-3"><h5>Applications by Status</h5><?php $counts=array_count_values(array_column($applications,'application_status'));foreach($counts as $status=>$count):?><p><?=e($status)?>: <?=e($count)?></p><?php endforeach;?></div>
<?php endif;require dirname(__DIR__).'/includes/footer.php';
